<?php require __DIR__.'/../inc/bootstrap.php'; if(admin()){header('Location:index.php');exit;} $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $u=$_POST['user']??'';$p=$_POST['pass']??''; if(hash_equals($config['admin_user']??'admin',$u) && password_verify($p,$config['admin_password_hash']??'')){session_regenerate_id(true);$_SESSION['admin']=true;header('Location:index.php');exit;} $error='ACCESS DENIED'; } ?><!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ADMIN LOGIN</title><link rel="stylesheet" href="../assets/style.css"></head><body><main class="container"><div class="card"><h1>[ ADMIN TERMINAL ]</h1><?php if($error): ?><p><?=e($error)?></p><?php endif; ?><form method="post"><input name="user" placeholder="USER" autocomplete="username"><input name="pass" type="password" placeholder="PASSWORD" autocomplete="current-password"><button>EXECUTE</button></form></div></main></body></html>
